ui.debug.addRules("hasunomura",[{rules:"Shade some cells on the board.\n1. Cells with numbers cannot be shaded.\n2. Clues indicate the sum of the areas of the unshaded regions using the (up to 4) cells diagonally adjacent to the clue. If a region uses multiple of these cells, it is only counted once. \n3. The shaded cells cannot form a 2x2 square.\n4. All shaded cells form an orthogonally contiguous area.",history:""},{rules:"盤面のいくつかの白マス全体を黒く塗り、黒マスとします\n1. すべての黒マスはタテヨコにひとつながりになっていなければなりません\n2. 黒マスが2×2以上のカタマリになってはいけません\n3. 数字は、その数字の入ったマスのナナメの位置にある白マスと、そこからタテヨコにひとつながりになる白マスの合計になります\n4. 数字の入ったマスを黒く塗ってはいけません",history:""}]),ui.debug.addDebugData("hasunomura",{url:"6/6/g2l2j2h5n6k6j",failcheck:[["brNoShade","pzprv3/hasunomura/6/6/. 2 . . . . /. . 2 . . . /. 2 . . 5 . /. . . . . . /. 6 . . . . /. 6 . . . . /. . . . . . /. . . . . . /. . . . . . /. . . . . . /. . . . . . /. . . . . . /"],["cs2x2","pzprv3/hasunomura/6/6/. 2 . . . . /. . 2 . . . /. 2 . . 5 . /. . . . . . /. 6 . . . . /. 6 . . . . /# . # # # # /# # . . # # /# . # # . # /# . . . . # /. . . . . . /. . . . . . /"],["bkSizeNe","pzprv3/hasunomura/6/6/. 2 . . . . /. . 2 . . . /. 2 . . 5 . /. . . . . . /. 6 . . . . /. 6 . . . . /# . # # # # /# # . # . # /# . # # . # /# # # . . # /. . # # . # /. . . . # # /"],["csDivide","pzprv3/hasunomura/6/6/. 2 . . . . /. . 2 . . . /. 2 . . 5 . /. . . . . . /. 6 . . . . /. 6 . . . . /# . # # # . /# # . . # # /# . # # . # /# # # . . # /# . . # # # /. . . . # . /"],[null,"pzprv3/hasunomura/6/6/. 2 . . . . /. . 2 . . . /. 2 . . 5 . /. . . . . . /. 6 . . . . /. 6 . . . . /# + # # # + /# # + + # # /# + # # + # /# # # + + # /+ + # # # # /+ + + + # + /"]],inputs:[]});
